const LEFT_OF = new Map<number, number>(MIRROR_PAIRS.map(([r, l]) => [r, l]));

/** Neutral template for all 478 points (unused points parked on the midline). */
export function neutralTemplate(): Vec2[] {
  const out: Vec2[] = Array.from({ length: NUM_LANDMARKS }, () => ({ x: 0, y: 0.3 }));
  for (const [k, [x, y]] of Object.entries(RIGHT_AND_MIDLINE)) {
    const i = Number(k);
    out[i] = { x, y };
    const l = LEFT_OF.get(i);
    if (l !== undefined) out[l] = { x: -x, y };
  }
  return out;
}

/** Displacements for the patient-RIGHT side at full amplitude: index → [dx(outward+), dy]. */
type Field = Record<number, [number, number]>;

const LID_PAIRS_RIGHT: [number, number][] = [
  [246, 7],
  [161, 163],
  [160, 144],
  [159, 145],
  [158, 153],
  [157, 154],
  [173, 155],
];

function eyeClosureField(T: readonly Vec2[], amount: number): Field {
  const f: Field = {};
  for (const [u, l] of LID_PAIRS_RIGHT) {
    f[u] = [0, amount * (T[l]!.y - T[u]!.y)];
    f[l] = [0, -0.01 * (amount / 0.88)];
  }
  return f;
}

function eyeNarrowField(T: readonly Vec2[], fraction: number): Field {
  // Lower lid rises 2/3 and upper lid drops 1/3 of the requested narrowing.
  const f: Field = {};
  for (const [u, l] of LID_PAIRS_RIGHT) {
    const h = T[l]!.y - T[u]!.y;
    f[u] = [0, (h * fraction) / 3];
    f[l] = [0, (-h * fraction * 2) / 3];
  }
  return f;
}

