export interface SyntheticSubject {
  affectedSide: Side;
  /** Movement amplitude of the affected side relative to the healthy side (0–1). */
  strength: number;
  /** Resting droop severity of the affected side (0–1). */
  droop: number;
  /** Synkinesis severity (0–1). */
  synkinesis: number;
  /**
   * Passive pull of the mouth towards the healthy side in mouth tasks (0–1),
   * scaled by the strength deficit. Lip midline moves fully, corners half.
   */
  drag?: number;
  /** Optional per-task strength overriding `strength` (regions recover at different rates). */
  taskStrength?: Partial<Record<MovementTaskId, number>>;
}

export interface SyntheticCamera {
  width: number;
  height: number;
  /** Inter-pupillary distance in pixels. */
  ipdPx: number;
  center: Vec2;
  rollDeg: number;
  yawDeg: number;
  /** Landmark noise SD in face units. */
  noise: number;
  luminance: number;
}

export const DEFAULT_CAMERA: SyntheticCamera = {
  width: 720,
  height: 960,
  ipdPx: 150,
  center: { x: 360, y: 400 },
  rollDeg: 0,
  yawDeg: 0,
  noise: 0.002,
  luminance: 130,
};

/** Deterministic PRNG (mulberry32) + Box–Muller normal. */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  const u = Math.max(r(), 1e-12);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r());
}

function applyField(pts: Vec2[], field: Field, side: Side, amplitude: number): void {
  if (amplitude === 0) return;
  const out = side === 'left' ? 1 : -1;
  for (const [k, [dx, dy]] of Object.entries(field)) {
    const r = Number(k);
    const i = side === 'right' ? r : (LEFT_OF.get(r) ?? r);
    // Field dx is "outward positive"; on the right side outward is −x.
    pts[i] = { x: pts[i]!.x + out * dx * amplitude, y: pts[i]!.y + dy * amplitude };
  }
}

/** Face-unit landmark shape for a task at a given activation level (0–1). */
export function syntheticShape(subject: SyntheticSubject, task: TaskId, activation: number): Vec2[] {
  const T = neutralTemplate();
  const pts = T.map((p) => ({ ...p }));
  const aff = subject.affectedSide;
  const healthy: Side = aff === 'left' ? 'right' : 'left';
  applyField(pts, REST_DROOP_FIELD, aff, subject.droop);
  if (task !== 'rest' && activation > 0) {
    const f = fieldFor(task, T);
    applyField(pts, f, healthy, activation);
    applyField(pts, f, aff, activation * (subject.taskStrength?.[task] ?? subject.strength));
    if (subject.synkinesis > 0) {
      const s = subject.synkinesis * activation;
      if (task === 'brow' || task === 'eyeClose') applyField(pts, { 61: [0.04, -0.03], 78: [0.035, -0.025] }, aff, s);
      else applyField(pts, eyeNarrowField(T, 0.45), aff, s);
    }
    // Passive drag of the lips towards the stronger side in mouth tasks.
    if ((task === 'smile' || task === 'pucker') && subject.drag) {
      const drag = 0.03 * subject.drag * activation * (1 - subject.strength) * (healthy === 'left' ? 1 : -1);
      for (const i of new Set([...CONTOURS.lipsOuter!, ...CONTOURS.lipsInner!])) {
        const w = Math.max(0, 1 - Math.abs(T[i]!.x) / 0.38 / 2); // 1 at midline, 0.5 at the corners
        pts[i] = { x: pts[i]!.x + drag * w, y: pts[i]!.y };
      }
    }
  }
  return pts;
}

/** Projects a face-unit shape into a normalised landmark frame. */
export function toObservation(shape: readonly Vec2[], cam: SyntheticCamera, t: number, random: () => number): FrameObservation {
  const th = (cam.rollDeg * Math.PI) / 180;
  const c = Math.cos(th);
  const s = Math.sin(th);
  const yawRad = (cam.yawDeg * Math.PI) / 180;
  const landmarks = new Array<number>(shape.length * 3);
  for (let i = 0; i < shape.length; i++) {
    const p = shape[i]!;
    // Cheap yaw: horizontal foreshortening plus depth offset (for the landmark-only pose estimate).
    const x0 = (p.x + gauss(random) * cam.noise) * Math.cos(yawRad);
    const y0 = p.y + gauss(random) * cam.noise;
    const z0 = p.x * Math.sin(yawRad);
    const x = cam.center.x + cam.ipdPx * (c * x0 - s * y0);
    const y = cam.center.y + cam.ipdPx * (s * x0 + c * y0);
    landmarks[3 * i] = x / cam.width;
    landmarks[3 * i + 1] = y / cam.height;
    landmarks[3 * i + 2] = (z0 * cam.ipdPx) / cam.width;
  }
  return {
    t,
    width: cam.width,
    height: cam.height,
    landmarks,
    pose: { yaw: cam.yawDeg, pitch: 0, roll: cam.rollDeg },
    luminance: { mean: cam.luminance, asymmetry: 0.04 },
  };
}

/** Activation profile of a recorded task: ramp up, hold, relax. */
function activationAt(i: number, n: number): number {
  const ramp = Math.max(1, Math.round(n * 0.25));
  if (i < ramp) return i / ramp;
  if (i > n - ramp) return Math.max(0, (n - i) / ramp);
  return 1;
}

export interface SyntheticSessionOptions {
  camera?: Partial<SyntheticCamera>;
  framesPerTask?: number;
  seed?: number;
}

export function syntheticSession(subject: SyntheticSubject, opts: SyntheticSessionOptions = {}) {
  const cam = { ...DEFAULT_CAMERA, ...opts.camera };
  const n = opts.framesPerTask ?? 24;
  const random = rng(opts.seed ?? 1);
  let t = 0;
  const rest: FrameObservation[] = [];
  const restShape = syntheticShape(subject, 'rest', 0);
  for (let i = 0; i < n; i++) rest.push(toObservation(restShape, cam, (t += 33), random));
  const tasks = {} as Record<MovementTaskId, FrameObservation[]>;
  for (const task of ['brow', 'eyeClose', 'smile', 'snarl', 'pucker'] as const) {
    tasks[task] = [];
    for (let i = 0; i < n; i++) {
      tasks[task].push(toObservation(syntheticShape(subject, task, activationAt(i, n)), cam, (t += 33), random));
    }
  }
  return { affectedSide: subject.affectedSide, rest, tasks };
}

// Guard: keep the template consistent with the index tables used by the measures.
for (const side of ['right'] as const) {
  for (const i of [...SIDE[side].brow, SIDE[side].mouthCorner, ...SIDE[side].ala, ...SIDE[side].upperLip]) {
    if (!(i in RIGHT_AND_MIDLINE)) throw new Error(`synthetic template misses landmark ${i}`);
  }
}
